def transform(grid):
    h, w = len(grid), len(grid[0])
    background = grid[0][0]

    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    ]
    # Separator color differs from the background.
    sep_rows = [r for r in sep_rows if grid[r][0] != background]
    sep_cols = [c for c in sep_cols if grid[0][c] != background]

    def intervals(size, separators):
        bounds = [-1] + separators + [size]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)]

    row_parts = intervals(h, sep_rows)
    col_parts = intervals(w, sep_cols)

    out = []
    for r0, r1 in row_parts:
        row = []
        for c0, c1 in col_parts:
            count = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if count >= 2 else background)
        out.append(row)
    return out
